/**
 * MatchPipeline — turns a directory into a decision engine.
 *
 *   Need → Location → Eligibility → Availability → Verification → Capacity
 *
 * Every stage records which resources it eliminated and why, so a Navigator (and
 * a judge) can see exactly why a resource was or was not suggested. Candidates
 * only ever come from the resource database — never generated by AI.
 */

export const NEED_CATEGORIES = [
  'employment',
  'training',
  'health',
  'legal',
  'documents',
  'shelter',
  'food',
  'social_assistance',
  'emergency',
] as const;
export type NeedCategory = (typeof NEED_CATEGORIES)[number];

/** Maps stored resource/need categories from every legacy vocabulary. */
export function normalizeNeedCategory(value: string | null | undefined): NeedCategory {
  const v = (value ?? '').trim().toLowerCase();
  switch (v) {
    case 'employment':
    case 'job':
    case 'livelihood':
      return 'employment';
    case 'training':
    case 'vocational':
      return 'training';
    case 'medical':
    case 'health':
      return 'health';
    case 'legal':
      return 'legal';
    case 'documents':
    case 'civil_documents':
    case 'identity':
      return 'documents';
    case 'shelter':
    case 'housing':
      return 'shelter';
    case 'food':
      return 'food';
    case 'emergency':
    case 'emergency_aid':
    case 'sos111':
      return 'emergency';
    default:
      return 'social_assistance';
  }
}

/** Categories that can legitimately serve a need (primary first). */
const SERVES: Record<NeedCategory, NeedCategory[]> = {
  employment: ['employment', 'training'],
  training: ['training', 'employment'],
  health: ['health'],
  legal: ['legal', 'documents'],
  documents: ['documents', 'legal', 'social_assistance'],
  shelter: ['shelter', 'social_assistance', 'emergency'],
  food: ['food', 'social_assistance'],
  social_assistance: ['social_assistance'],
  emergency: ['emergency', 'health', 'shelter'],
};

/** Pilot geography: Hóc Môn ↔ Quận 12 are adjacent and share many services. */
const ADJACENT: Record<string, string[]> = {
  'hoc mon': ['quan 12', 'cu chi', 'binh tan', 'go vap'],
  'quan 12': ['hoc mon', 'go vap', 'binh tan', 'tan binh'],
};

const CITYWIDE_TOKENS = ['toan tp', 'toan thanh pho', 'tp.hcm', 'tp hcm', 'citywide', 'all'];

export function normalizeDistrict(value: string | null | undefined): string {
  return (value ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/đ/g, 'd')
    .replace(/^(huyen|quan|district|h\.|q\.)\s*/, (m) => (m.startsWith('q') || m.startsWith('d') ? 'quan ' : ''))
    .replace(/\s+/g, ' ')
    .trim();
}

export type VerificationFreshness = 'VERIFIED' | 'NEEDS_RECHECK' | 'UNCONFIRMED' | 'INACTIVE';
export type CapacityStatus = 'AVAILABLE' | 'LIMITED' | 'FULL' | 'UNKNOWN';

export interface DirectoryResource {
  id: string;
  name: string;
  organisationName?: string | null;
  serviceName?: string | null;
  category: string;
  district: string;
  address?: string | null;
  /** Districts served. Empty = only its own district. Contains a citywide token = all. */
  serviceArea?: string[] | null;
  eligibility?: {
    minAge?: number | null;
    maxAge?: number | null;
    targetGroups?: string[] | null;
    requiresIdentityDoc?: boolean | null;
  } | null;
  availability?: {
    /** e.g. ["mon","tue","wed","thu","fri"] */
    days?: string[] | null;
    /** "07:30-17:00" */
    hours?: string | null;
  } | null;
  acceptsReferral?: boolean | null;
  verificationStatus?: string | null;
  verifiedAt?: string | null;
  verificationExpiresAt?: string | null;
  capacityStatus?: string | null;
  slotsAvailable?: number | null;
  /** Free-text used for strength matching (description, tags) */
  keywords?: string | null;
}

export interface NeedProfile {
  need: string;
  district: string;
  age?: number | null;
  targetGroup?: string | null;
  hasIdentityDoc?: boolean | null;
  constraints?: {
    daytimeOnly?: boolean;
    weekendOnly?: boolean;
  };
  strengths?: string[];
  /** When true (RiskGate), employment resources are removed at the Eligibility stage */
  blockEmployment?: boolean;
}

export const MATCH_STAGES = ['need', 'location', 'eligibility', 'availability', 'verification', 'capacity'] as const;
export type MatchStage = (typeof MATCH_STAGES)[number];

/** Machine-readable reason so every UI language can explain the decision. */
export type MatchReasonCode =
  | 'NOT_THIS_NEED'
  | 'OUTSIDE_AREA'
  | 'SAFEGUARDING_EMPLOYMENT_BLOCK'
  | 'MIN_AGE'
  | 'MAX_AGE'
  | 'TARGET_GROUP'
  | 'REQUIRES_ID'
  | 'NOT_ACCEPTING_REFERRALS'
  | 'CLOSED_WEEKENDS'
  | 'NIGHT_ONLY'
  | 'INACTIVE'
  | 'UNCONFIRMED'
  | 'FULL'
  | 'NO_SLOTS'
  | 'PROVIDES_NEED'
  | 'RELATED_SERVICE'
  | 'SAME_DISTRICT'
  | 'ADJACENT_DISTRICT'
  | 'CITYWIDE'
  | 'VERIFIED_ON'
  | 'STRENGTH'
  | 'NEEDS_RECHECK'
  | 'LIMITED_CAPACITY'
  | 'CAPACITY_UNKNOWN';

export interface MatchReason {
  code: MatchReasonCode;
  value?: string | number;
}

export interface StageReport {
  stage: MatchStage;
  inCount: number;
  passedCount: number;
  eliminated: Array<{ resourceId: string; resourceName: string; reason: string; code: MatchReasonCode; value?: string | number }>;
}

export interface MatchCandidate {
  resource: DirectoryResource;
  score: number;
  freshness: Extract<VerificationFreshness, 'VERIFIED' | 'NEEDS_RECHECK'>;
  locationFit: 'same_district' | 'adjacent' | 'citywide';
  reasons: string[];
  warnings: string[];
  reasonCodes: MatchReason[];
  warningCodes: MatchReason[];
  /** true when the Navigator must call to confirm before a referral is sent */
  mustConfirmBeforeReferral: boolean;
}

export interface MatchPipelineResult {
  need: NeedCategory;
  stages: StageReport[];
  candidates: MatchCandidate[];
}

const DEFAULT_VERIFICATION_TTL_DAYS = 90;
const INACTIVE_STATUSES = ['INACTIVE', 'UNAVAILABLE'];
const UNCONFIRMED_STATUSES = ['UNCONFIRMED', 'UNVERIFIED', 'PENDING'];

/** Resolves stored verification data into the three user-facing states (+ inactive). */
export function resolveVerificationFreshness(
  r: Pick<DirectoryResource, 'verificationStatus' | 'verifiedAt' | 'verificationExpiresAt'>,
  now: Date = new Date(),
): VerificationFreshness {
  const status = (r.verificationStatus ?? 'UNCONFIRMED').toUpperCase();
  if (INACTIVE_STATUSES.includes(status)) return 'INACTIVE';
  if (UNCONFIRMED_STATUSES.includes(status)) return 'UNCONFIRMED';
  if (status === 'NEEDS_RECHECK' || status === 'STALE') return 'NEEDS_RECHECK';
  // VERIFIED — still must be fresh
  if (!r.verifiedAt) return 'NEEDS_RECHECK';
  const expires = r.verificationExpiresAt
    ? new Date(r.verificationExpiresAt).getTime()
    : new Date(r.verifiedAt).getTime() + DEFAULT_VERIFICATION_TTL_DAYS * 86_400_000;
  if (Number.isNaN(expires) || expires < now.getTime()) return 'NEEDS_RECHECK';
  return 'VERIFIED';
}

function parseHours(hours: string | null | undefined): { open: number; close: number } | null {
  if (!hours) return null;
  const m = hours.match(/(\d{1,2})[:h](\d{2})?\s*[-–]\s*(\d{1,2})[:h](\d{2})?/);
  if (!m) return null;
  return { open: Number(m[1]) * 60 + Number(m[2] ?? 0), close: Number(m[3]) * 60 + Number(m[4] ?? 0) };
}

function locationFitOf(resource: DirectoryResource, district: string): MatchCandidate['locationFit'] | null {
  const target = normalizeDistrict(district);
  const home = normalizeDistrict(resource.district);
  const area = (resource.serviceArea ?? []).map(normalizeDistrict);
  if (home === target || area.includes(target)) return 'same_district';
  if (area.some((a) => CITYWIDE_TOKENS.some((t) => a.includes(t)))) return 'citywide';
  if ((ADJACENT[target] ?? []).includes(home)) return 'adjacent';
  return null;
}

type Check = (r: DirectoryResource) => (MatchReason & { text: string }) | null;

function runStage(stage: MatchStage, pool: DirectoryResource[], check: Check): { report: StageReport; passed: DirectoryResource[] } {
  const passed: DirectoryResource[] = [];
  const eliminated: StageReport['eliminated'] = [];
  for (const r of pool) {
    const hit = check(r);
    if (hit) eliminated.push({ resourceId: r.id, resourceName: r.name, reason: hit.text, code: hit.code, value: hit.value });
    else passed.push(r);
  }
  return { report: { stage, inCount: pool.length, passedCount: passed.length, eliminated }, passed };
}

/** English fallback text for API consumers; UIs translate `code` instead. */
export function reasonText(r: MatchReason): string {
  switch (r.code) {
    case 'PROVIDES_NEED':
      return `Provides ${r.value} support`;
    case 'RELATED_SERVICE':
      return `Related service (${r.value})`;
    case 'SAME_DISTRICT':
      return 'Serves this district';
    case 'ADJACENT_DISTRICT':
      return 'Neighbouring district';
    case 'CITYWIDE':
      return 'Serves the whole city';
    case 'VERIFIED_ON':
      return r.value ? `Verified ${r.value}` : 'Verified';
    case 'STRENGTH':
      return `Builds on strength: ${r.value}`;
    case 'NEEDS_RECHECK':
      return 'Verification needs re-check — call to confirm before sending the referral';
    case 'LIMITED_CAPACITY':
      return 'Limited capacity';
    case 'CAPACITY_UNKNOWN':
      return 'Capacity not confirmed';
    default:
      return r.code;
  }
}

export function runMatchPipeline(
  profile: NeedProfile,
  resources: DirectoryResource[],
  now: Date = new Date(),
): MatchPipelineResult {
  const need = normalizeNeedCategory(profile.need);
  const servedBy = SERVES[need];
  const stages: StageReport[] = [];
  let pool = resources;

  const step = (stage: MatchStage, check: Check) => {
    const { report, passed } = runStage(stage, pool, check);
    stages.push(report);
    pool = passed;
  };

  step('need', (r) =>
    servedBy.includes(normalizeNeedCategory(r.category)) ? null : { code: 'NOT_THIS_NEED', value: need, text: `Does not provide ${need} support` },
  );

  step('location', (r) => (locationFitOf(r, profile.district) ? null : { code: 'OUTSIDE_AREA', value: profile.district, text: `Outside service area for ${profile.district}` }));

  step('eligibility', (r) => {
    const e = r.eligibility ?? {};
    const category = normalizeNeedCategory(r.category);
    if (profile.blockEmployment && (category === 'employment' || category === 'training')) {
      return { code: 'SAFEGUARDING_EMPLOYMENT_BLOCK', text: 'Safeguarding: employment referral blocked for this person' };
    }
    if (profile.age != null) {
      if (e.minAge != null && profile.age < e.minAge) return { code: 'MIN_AGE', value: e.minAge, text: `Minimum age ${e.minAge}` };
      if (e.maxAge != null && profile.age > e.maxAge) return { code: 'MAX_AGE', value: e.maxAge, text: `Maximum age ${e.maxAge}` };
    }
    const groups = (e.targetGroups ?? []).map((g) => g.toLowerCase());
    if (profile.targetGroup && groups.length > 0 && !groups.includes('any') && !groups.includes(profile.targetGroup.toLowerCase())) {
      return { code: 'TARGET_GROUP', value: groups.join(', '), text: `Serves ${groups.join(', ')} only` };
    }
    if (e.requiresIdentityDoc && profile.hasIdentityDoc === false) return { code: 'REQUIRES_ID', text: 'Requires identity documents' };
    return null;
  });

  step('availability', (r) => {
    if (r.acceptsReferral === false) return { code: 'NOT_ACCEPTING_REFERRALS', text: 'Not accepting referrals' };
    const a = r.availability ?? {};
    const days = (a.days ?? []).map((d) => d.toLowerCase());
    if (profile.constraints?.weekendOnly && days.length > 0 && !days.some((d) => d === 'sat' || d === 'sun')) {
      return { code: 'CLOSED_WEEKENDS', text: 'Closed on weekends' };
    }
    const h = parseHours(a.hours);
    if (profile.constraints?.daytimeOnly && h && (h.close <= 7 * 60 || h.open >= 18 * 60)) {
      return { code: 'NIGHT_ONLY', text: 'Only open outside daytime hours' };
    }
    return null;
  });

  step('verification', (r) => {
    const f = resolveVerificationFreshness(r, now);
    if (f === 'INACTIVE') return { code: 'INACTIVE', text: 'Marked inactive' };
    if (f === 'UNCONFIRMED') return { code: 'UNCONFIRMED', text: 'Not yet verified by a person' };
    return null;
  });

  step('capacity', (r) => {
    const c = (r.capacityStatus ?? 'UNKNOWN').toUpperCase();
    if (c === 'FULL') return { code: 'FULL', text: 'No capacity right now' };
    if (r.slotsAvailable != null && r.slotsAvailable <= 0) return { code: 'NO_SLOTS', text: 'No slots left' };
    return null;
  });

  const strengths = (profile.strengths ?? []).map((s) => s.toLowerCase()).filter(Boolean);
  const candidates: MatchCandidate[] = pool.map((r) => {
    const freshness = resolveVerificationFreshness(r, now) as MatchCandidate['freshness'];
    const locationFit = locationFitOf(r, profile.district)!;
    const capacity = (r.capacityStatus ?? 'UNKNOWN').toUpperCase() as CapacityStatus;
    const reasonCodes: MatchReason[] = [];
    const warningCodes: MatchReason[] = [];
    let score = 0;

    if (normalizeNeedCategory(r.category) === servedBy[0]) {
      score += 15;
      reasonCodes.push({ code: 'PROVIDES_NEED', value: need });
    } else {
      score += 8;
      reasonCodes.push({ code: 'RELATED_SERVICE', value: normalizeNeedCategory(r.category) });
    }

    score += locationFit === 'same_district' ? 30 : locationFit === 'adjacent' ? 20 : 15;
    reasonCodes.push({ code: locationFit === 'same_district' ? 'SAME_DISTRICT' : locationFit === 'adjacent' ? 'ADJACENT_DISTRICT' : 'CITYWIDE' });

    if (freshness === 'VERIFIED') {
      score += 35;
      reasonCodes.push({ code: 'VERIFIED_ON', value: r.verifiedAt ? r.verifiedAt.slice(0, 10) : undefined });
    } else {
      score += 15;
      warningCodes.push({ code: 'NEEDS_RECHECK' });
    }

    if (capacity === 'AVAILABLE') score += 20;
    else if (capacity === 'LIMITED') {
      score += 10;
      warningCodes.push({ code: 'LIMITED_CAPACITY' });
    } else if (capacity === 'UNKNOWN') {
      score += 5;
      warningCodes.push({ code: 'CAPACITY_UNKNOWN' });
    }

    const haystack = `${r.name} ${r.serviceName ?? ''} ${r.keywords ?? ''}`.toLowerCase();
    const matchedStrength = strengths.find((s) => haystack.includes(s));
    if (matchedStrength) {
      score += 10;
      reasonCodes.push({ code: 'STRENGTH', value: matchedStrength });
    }

    const reasons = reasonCodes.map(reasonText);
    const warnings = warningCodes.map(reasonText);

    return {
      resource: r,
      score: Math.min(100, score),
      freshness,
      locationFit,
      reasons,
      warnings,
      reasonCodes,
      warningCodes,
      mustConfirmBeforeReferral: freshness !== 'VERIFIED' || capacity === 'UNKNOWN',
    };
  });

  candidates.sort((a, b) => b.score - a.score || a.resource.name.localeCompare(b.resource.name));
  return { need, stages, candidates };
}
